export const VIETCOMBANK_LOGO_DATA_URL = "data:image/svg+xml;base64,";

// Cache for preloaded images so canvas drawing is immediate and synchronous
const imageCache = new Map<string, HTMLImageElement>();

export function getCachedLogoImage(src: string = VIETCOMBANK_LOGO_DATA_URL, onReady?: () => void): HTMLImageElement {
  if (imageCache.has(src)) {
    const existing = imageCache.get(src)!;
    if (existing.complete && existing.naturalWidth > 0) {
      return existing;
    }
  }

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = src;
  if (onReady) {
    img.onload = () => onReady();
  }
  imageCache.set(src, img);
  return img;
}

/**
 * Draws the Vietcombank logo onto an HTML5 2D Canvas.
 * Handles both the official SVG logo, custom uploaded image from localStorage,
 * and an immediate vector/text fallback so nothing is blank while loading.
 */
export function drawUncLogo(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number = 175,
  height: number = 30.5,
  customSrc?: string | null,
  onLoaded?: () => void
): void {
  const effectiveSrc = (customSrc && customSrc.trim()) ? customSrc.trim() : VIETCOMBANK_LOGO_DATA_URL;
  const img = getCachedLogoImage(effectiveSrc, onLoaded);

  if (img.complete && img.naturalWidth > 0) {
    // Preserve aspect ratio if custom image or standard logo
    const imgRatio = img.naturalWidth / img.naturalHeight;
    const boxRatio = width / height;
    let drawW = width;
    let drawH = height;
    let drawX = x;
    let drawY = y;

    if (imgRatio > boxRatio) {
      drawW = width;
      drawH = width / imgRatio;
      drawY = y + (height - drawH) / 2;
    } else {
      drawH = height;
      drawW = height * imgRatio;
      drawX = x;
      drawY = y + (height - drawH) / 2;
    }

    ctx.drawImage(img, drawX, drawY, drawW, drawH);
    return;
  }

  // Fallback if image is still parsing/loading: render authentic vector emblem & bold text
  drawVietcombankVectorFallback(ctx, x, y, width, height);
}

/**
 * Immediate vector fallback that renders the iconic green ribbon loop
 * and the "Vietcombank" text directly via Canvas 2D commands.
 */
export function drawVietcombankVectorFallback(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number
): void {
  ctx.save();

  const scale = height / 29;
  const iconSize = 29 * scale;

  // 1. Draw 3D-styled green loop ribbon
  const cx = x + iconSize / 2;
  const cy = y + iconSize / 2;
  const r = iconSize * 0.42;

  // Gradient for outer ribbon loop
  const grad = ctx.createLinearGradient(x, y, x + iconSize, y + iconSize);
  grad.addColorStop(0, "#92C03E");
  grad.addColorStop(0.3, "#70B445");
  grad.addColorStop(0.7, "#1A5F30");
  grad.addColorStop(1, "#034C2D");

  ctx.strokeStyle = grad;
  ctx.lineWidth = iconSize * 0.22;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  ctx.beginPath();
  // Triangular rounded loop
  ctx.moveTo(cx - r * 0.7, cy + r * 0.8);
  ctx.bezierCurveTo(cx - r * 1.1, cy + r * 0.2, cx - r * 0.8, cy - r * 0.9, cx, cy - r);
  ctx.bezierCurveTo(cx + r * 0.8, cy - r * 0.9, cx + r * 1.1, cy + r * 0.2, cx + r * 0.7, cy + r * 0.8);
  ctx.bezierCurveTo(cx + r * 0.4, cy + r * 1.1, cx - r * 0.4, cy + r * 1.1, cx - r * 0.7, cy + r * 0.8);
  ctx.stroke();

  // Highlight inner loop curve
  const grad2 = ctx.createLinearGradient(x + iconSize * 0.3, y, x + iconSize, y + iconSize * 0.5);
  grad2.addColorStop(0, "#034C2D");
  grad2.addColorStop(0.5, "#286A31");
  grad2.addColorStop(1, "#92C03E");
  ctx.strokeStyle = grad2;
  ctx.lineWidth = iconSize * 0.16;
  ctx.beginPath();
  ctx.arc(cx + r * 0.15, cy - r * 0.15, r * 0.55, -0.6 * Math.PI, 0.4 * Math.PI);
  ctx.stroke();

  // 2. Draw "Vietcombank" text
  const textX = x + iconSize + 8 * scale;
  const textY = y + height * 0.76;
  ctx.fillStyle = "#034C2D";
  ctx.font = `bold ${Math.round(20 * scale)}px "Trebuchet MS", "Arial", sans-serif`;
  ctx.textAlign = "left";
  ctx.fillText("Vietcombank", textX, textY);

  ctx.restore();
}
